import{_ as i,l as s,o,c as l,v as e,p as n,x as t,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"序列化：JSON / Protobuf","description":"","frontmatter":{"title":"序列化：JSON / Protobuf","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/serialization-protobuf.md","filePath":"cs/serialization-protobuf.md","lastUpdated":1789023840000}'),h={name:"cs/serialization-protobuf.md"};function f(u,a,P,b,S,T){const r=s("Mermaid");return o(),l("div",null,[a[1]||(a[1]=e('<h1 id="序列化-json-protobuf" tabindex="-1">序列化：JSON / Protobuf <a class="header-anchor" href="#序列化-json-protobuf" aria-label="Permalink to &quot;序列化：JSON / Protobuf&quot;">​</a></h1><div class="epigraph"><p>JSON 是自描述文本，便于调试与浏览器；Protobuf 是带 schema 的二进制，省带宽与 CPU。都是应用编码，不是 HTTP。</p><footer>—— 据 RFC 8259 JSON；Protobuf 语言指南整理</footer></div><p><a href="/cs/rest-grpc">上一课</a> 假定有一种编码。<a href="/cs/content-negotiation">内容协商</a> 可选 <code>application/json</code>。缺口是<strong>编码本身</strong>：字段、版本、与报文成帧。本课结束 HTTP 与 Web 协议课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程内存结构不能直接上<a href="/cs/socket-api">套接字</a>。JSON：Unicode 文本、对象图、无原生二进制（用 base64）。Protobuf：字段号、varint、向前兼容靠未识别字段保留。gRPC 默认后者。压缩可再叠 gzip，但 Protobuf 已密，收益小。schema 演化：加可选字段易，改语义难——与 DB 模式后课不同栏，这里只钉报文。</p><p>不要把 Protobuf 写成加密。</p><p><span class="marginnote">RFC 8259。Protobuf 是 Google 开文档的 IDL。本课不把每种 IDL（Thrift/Avro）列完。</span></p><h3 id="编码不等于成帧" tabindex="-1">编码不等于成帧 <a class="header-anchor" href="#编码不等于成帧" aria-label="Permalink to &quot;编码不等于成帧&quot;">​</a></h3><p>JSON 自描述；Protobuf 靠字段号。无长度前缀仍会粘包。schema 演化属于合同。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：可读 vs 紧凑；有无 schema。画：结构 → 字节 → 解析。与线路码对照：一层在 PHY，一层在应用。粘包后课：Protobuf 消息仍要长度前缀或 gRPC 帧。</p>',11)),(o(),n(d,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%86%85%E5%AD%98%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20JSON%5B%22%E8%87%AA%E6%8F%8F%E8%BF%B0%E6%96%87%E6%9C%AC%22%5D%0A%20%20OBJ%20--%3E%20PB%5B%22%E5%AD%97%E6%AE%B5%E5%8F%B7%E4%BA%8C%E8%BF%9B%E5%88%B6%22%5D%0A%20%20PB%20--%3E%20WIRE%5B%22%E5%86%8D%E8%BF%9B%20HTTP%2FgRPC%20%E5%B8%A7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CPU：JSON 解析在 10G 上可成瓶颈，TSO 帮不上。QUIC 0-RTT 重放对非幂等 POST+JSON 危险。CDN 可缓存 GET+JSON，难缓存 gRPC。IPv6 过渡不影响编码。</p><p>安全：JSON 炸弹、Protobuf 递归深度是解析器边界。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ASN.1 的全部。DNS 缓存与 TTL 是下一课序第一课。后课默认：JSON 易互通；Protobuf 要 schema 与帧。</p><p>无长度的 JSON 流会粘包，不能只靠 TCP。</p><p>上一课留下的缺口在本课收口；「序列化：JSON / Protobuf」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/dns-cache-ttl">DNS 缓存与 TTL</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>JSON 自描述；Protobuf 靠字段号与 schema。</li><li>编码不等于运输，还要成帧。</li><li>演化规则属于合同，不是语法边角。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 8259；Protobuf 文档。</li></ul>',10))])}const E=i(h,[["render",f]]);export{m as __pageData,E as default};
